"""Cron-style schedules. SCHEDULE.md has the full rules."""

import calendar
import re
from dataclasses import dataclass
from datetime import date, datetime, timedelta

_WINDOW = timedelta(days=20 * 365)

_SHORTCUTS = {
    "@yearly": "0 0 1 1 *",
    "@annually": "0 0 1 1 *",
    "@monthly": "0 0 1 * *",
    "@weekly": "0 0 * * 0",
    "@daily": "0 0 * * *",
    "@midnight": "0 0 * * *",
    "@hourly": "0 * * * *",
}
_MONTHS = {n: i for i, n in enumerate(
    ["jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec"], start=1)}
_DAYS = {n: i for i, n in enumerate(["sun", "mon", "tue", "wed", "thu", "fri", "sat"])}

# (field name, lowest value, highest value, names or None)
_FIELDS = (
    ("minute", 0, 59, None),
    ("hour", 0, 23, None),
